/**
 * 3D Tiles layer — real textured building meshes from 6-NW-12D.
 *
 * ## Why 3D Tiles rather than individual Model.fromGltf calls
 *
 * One draw call vs 390. The tileset also gets Cesium's built-in frustum
 * culling and batched rendering for free. The `.b3dm` is generated by
 * `backend/scripts/build_3dtiles.py`, which reads the full mesh data from
 * each glTF (not just the AABB) and transforms every vertex to ECEF so
 * `tileset.json` uses an identity transform.
 */
import { Cesium3DTileset, type Viewer } from 'cesium'

export interface TilesetHandle {
  tileset: Cesium3DTileset
  dispose: () => void
}

/**
 * Load a 3D Tiles tileset from a URL and add it to the scene.
 *
 * Failure is logged rather than thrown: a missing or malformed tileset must not
 * take the scene down, exactly like a missing city model or waterbody layer.
 */
export async function add3DTileset(
  viewer: Viewer,
  url: string,
): Promise<TilesetHandle | null> {
  if (viewer.isDestroyed()) return null

  console.log('[3dtiles] loading tileset from', url)

  try {
    const tileset = await Cesium3DTileset.fromUrl(url, {
      maximumScreenSpaceError: 1,
    })
    if (viewer.isDestroyed()) {
      tileset.destroy()
      return null
    }

    tileset.allTilesLoaded.addEventListener(() => {
      console.log('[3dtiles] all tiles loaded')
    })

    tileset.tileFailed.addEventListener((event) => {
      console.error('[3dtiles] tile failed:', event)
    })

    viewer.scene.primitives.add(tileset)
    viewer.scene.requestRender()
    console.log('[3dtiles] tileset added to scene')
    return {
      tileset,
      dispose: () => {
        if (!viewer.isDestroyed()) {
          viewer.scene.primitives.remove(tileset)
        } else {
          tileset.destroy()
        }
      },
    }
  } catch (err) {
    console.warn('[3dtiles] failed to load tileset:', err)
    return null
  }
}
